"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10851"],{35233(e){e.exports=JSON.parse('{"id":"FIN-263","slug":"convexity","term":"Convexity","also_known_as":[],"difficulty":"Intermediate","definition":"Convexity measures how a bond\'s sensitivity to interest rates itself changes as rates move. It explains why bond prices do not change in a straight line when yields rise or fall.","explanation":["Duration gives a straight-line estimate of how much a bond\'s price will change when yields change. In reality, the relationship between price and yield is curved. Convexity measures that curve.","For a typical bond, the curve works in the investor\'s favour. When yields fall, the price rises a little more than duration predicts. When yields rise, the price falls a little less than duration predicts.","Take a ten-year bond with a 5% coupon priced at 1,000, with a modified duration of about 7.7. Duration alone suggests that a one-percentage-point rise in yield would lower the price to about 923, and a one-point fall would raise it to about 1,077. The actual prices are about 926 and 1,081. The small extra gain in both cases comes from convexity.","Convexity matters more for large rate changes and for long-term bonds. Bonds with higher convexity are generally more valuable, all else equal. Some bonds, such as callable bonds, can have negative convexity, meaning their price gains are limited when rates fall because the issuer is likely to repay them early."],"note":"","total":1500,"prev":{"slug":"convertible-note","term":"Convertible Note"},"next":{"slug":"copayment","term":"Copayment"}}')}}]);